from typing import List

class Solution:
    def numRescueBoats(self, people: List[int], limit: int) -> int:
        people = people[:]
        boats = 0
        while people:
            people.sort()
            heavy = people.pop()
            partner_index = -1
            for i, weight in enumerate(people):
                if weight + heavy <= limit:
                    partner_index = i
            if partner_index != -1:
                people.pop(partner_index)
            boats += 1
        return boats

