from typing import List

class Solution:
    def numRescueBoats(self, people: List[int], limit: int) -> int:
        people.sort()
        used = [False] * len(people)
        boats = 0
        for i in range(len(people) - 1, -1, -1):
            if used[i]:
                continue
            used[i] = True
            for j in range(i):
                if not used[j] and people[i] + people[j] <= limit:
                    used[j] = True
                    break
            boats += 1
        return boats

